   if len(active[label])<12:active[label].append({'pid':int(proc.name),'comm':comm,'via':'cmdline' if path in args else 'cwd'})
out['consumer_matches']=active
for service in services:
 c,text=cmd(['systemctl','show',service,'-p','ExecStart','-p','ExecStartPre','-p','ExecStartPost','-p','EnvironmentFile','-p','WorkingDirectory','--no-pager'])
