 if refs:out['systemd_matches'][service]=refs
for base in ('/etc/nginx/sites-enabled','/etc/nginx/conf.d'):
 p=Path(base)
 if p.is_dir():
  for f in p.iterdir():
   try:
    if f.is_file() and f.stat().st_size<300000:
     s=f.read_text(errors='replace')
     labels=[label for label,p in targets.items() if str(p) in s]
     if labels:out['nginx_files_with_matches'][str(f)]=labels
   except (PermissionError,OSError):continue
